    steps: function(v) { const ke=0.5*v.mass*v.velocity*v.velocity; return ['Formula: KE = ½ × m × v²','Step 1: v² = '+v.velocity+'² = '+v.velocity*v.velocity,'Step 2: KE = 0.5 × '+v.mass+' × '+v.velocity*v.velocity,'Step 3: KE = '+ke.toFixed(2)+' J']; },
