    calc: function(v){var speeds={air:331.3+0.606*v.temp,water:1480,steel:5960,wood:3300};var s=speeds[v.medium];return{result:'Speed: '+s.toFixed(1)+' m/s',chart:Charts.bar([s,343],['This','Air (0°C)']),extra:v.medium+' at '+v.temp+'°C'};},
